
from marshmallow import Schema, fields, validate


class UserSchema(Schema):
    id = fields.Integer(dump_only=True)
    username = fields.String(required=True, validate=validate.Length(min=3, max=80))
    email = fields.Email(required=True)
    role = fields.String(dump_only=True)


class DistrictSchema(Schema):
    id = fields.Integer(dump_only=True)
    name = fields.String(required=True, validate=validate.Length(max=100))


class ReportSchema(Schema):
    # Generated by the database
    id = fields.Integer(dump_only=True)

    # Assigned by the backend, not the resident
    user_id = fields.Integer(dump_only=True)
    reviewed_by = fields.Integer(dump_only=True, allow_none=True)

    # Supplied by the resident
    district_id = fields.Integer(
        required=True,
        validate=validate.Range(min=1)
    )
    location = fields.String(
        required=True,
        validate=validate.Length(min=1, max=150)
    )
    severity = fields.String(
        required=True,
        validate=validate.OneOf(["Critical", "High", "Moderate", "Low"])
    )
    time_without_water = fields.String(
        required=True,
        validate=validate.Length(min=1, max=100)
    )
    description = fields.String(required=True)

    # Controlled by the backend/admin
    status = fields.String(dump_only=True)
    created_at = fields.DateTime(dump_only=True)
